 return f'''<article class="project-feature {tone}"><div class="feature-copy"><div class="eyebrow" style="opacity:.7">{num} / {cat}</div><h3>{heading}</h3><p>{copy}</p><div class="label-row" style="margin-top:22px">{taghtml}</div><a class="bottom-link" href="{slug}">Explore case study ↗</a></div><div class="feature-visual">{visual}</div></article>'''

