work=f'''<section class="page-head"><div class="container"><div class="eyebrow blue">SELECTED PROJECTS / 2026</div><h1 class="large-title">A collection of<br><span class="dim">real-world work.</span></h1><div class="work-intro"><p class="body-lede">Projects from enterprise healthcare, e-commerce and application development. Each one reflects a different set of constraints and responsibilities.</p><div class="small-index">04 SELECTED PROJECTS</div></div></div></section><section class="section" style="padding-top:0"><div class="container"><div class="filter-bar" aria-label="Project filters"><button class="filter active" data-filter="all">All projects</button><button class="filter" data-filter="professional">Professional</button><button class="filter" data-filter="personal">Personal</button></div>{''.join(f'<article class="work-entry" data-category="{"personal" if key=="behbod" else "professional"}"><div class="work-info"><div class="eyebrow blue">{eyebrow}</div><h2>{name}</h2><p>{desc}</p><div class="eyebrow muted" style="font-size:10px;letter-spacing:.06em;margin-top:23px">{tech}</div>{f'<a class="inline-link" href="{link}">Read case study ↗</a>' if link!="#" else '<span class="footnote">Full case study coming soon</span>'}</div><div class="work-cover {tone}">{visual}</div></article>' for key,eyebrow,name,desc,link,tech,tone,visual in entries)}<div class="notice" style="margin-top:25px">Dashboard and storefront visuals in this design reference are illustrative placeholders. Replace them with approved, real project screenshots before publishing.</div></div></section>'''

